    out=[]
    for row in grid:
        r=row[:]
        for i in range(0,len(r)-1,2): r[i],r[i+1]=r[i+1],r[i]
        out.append(r)
    return out"},{"nl":"Move every nonzero cell one position to the right when possible, leaving zeros behind.","code":"def transform(grid):
    out=[row[:] for row in grid]
    for i,row in enumerate(grid):
        for j in range(len(row)-2,-1,-1):
            if row[j]!=0 and row[j+1]==0:
                out[i][j+1],out[i][j]=row[j],0
    return out"},{"nl":"Change each cell to the color of its nearest nonzero cell in the same row, with ties resolved to the left.","code":"def transform(grid):
    out=[]
    for row in grid:
        nz=[j for j,x in enumerate(row) if x!=0]
        if not nz: out.append(row[:]); continue
        out.append([row[min(nz,key=lambda j:(abs(j-k),j))] for k in range(len(row))])
    return out"},{"nl":"For each color, replace all occurrences by the next color modulo 10, leaving background zero unchanged.","code":"def transform(grid):
    return [[0 if x==0 else (x+1)%10 for x in row] for row in grid]"}]}

